function RealFileTree({ projectId, activeFile, onSelect }: { projectId: string; activeFile: string; onSelect: (file: string) => void }) { const [files, setFiles] = useState<{ path: string; type: string }[]>([]); const [error, setError] = useState(''); useEffect(() => { fetch(`/api/projects/${projectId}/files`, { credentials: 'include' }).then(async (r) => { if (!r.ok) throw new Error((await r.json()).error); return r.json(); }).then(setFiles).catch((reason) => setError(reason.message)); }, [projectId]); if (error) return <p className="p-3 text-[10px] text-red-300">{error}</p>; if (!files.length) return <p className="p-3 text-[10px] text-white/35">No files yet. Import a project or create a file through an agent.</p>; return <div className="space-y-1 p-3">{files.map((file) => file.type === 'directory' ? <div key={file.path} className="flex gap-1.5 py-1 text-[11px] text-white/55"><Folder size={13} className="text-[#c7a37b]" />{file.path}</div> : <button key={file.path} type="button" onClick={() => onSelect(file.path)} className={`flex w-full gap-1.5 rounded px-2 py-1 text-left text-[11px] ${activeFile === file.path ? 'bg-white/10 text-white' : 'text-white/50 hover:bg-white/5'}`}><FileCode2 size={12} />{file.path}</button>)}</div>; }
function RealCodeSurface({ projectId, activeFile }: { projectId: string; activeFile: string }) { const [content, setContent] = useState(''); const [status, setStatus] = useState(''); useEffect(() => { if (!activeFile) return; setStatus('Loading…'); fetch(`/api/projects/${projectId}/files/content?path=${encodeURIComponent(activeFile)}`, { credentials: 'include' }).then(async (r) => { if (!r.ok) throw new Error((await r.json()).error); return r.json(); }).then((data) => { setContent(data.content); setStatus('Saved'); }).catch((error) => setStatus(error.message)); }, [projectId, activeFile]); const save = async () => { const response = await fetch(`/api/projects/${projectId}/files/content`, { method: 'PUT', credentials: 'include', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ path: activeFile, content }) }); setStatus(response.ok ? 'Saved' : 'Could not save'); }; return <div className="flex h-full min-w-[620px] flex-col p-5 font-mono text-[11px] text-white/75 sm:p-7"><div className="mb-4 flex items-center gap-2 text-white/40"><FileCode2 size={13} /><span>{activeFile || 'Select a file'}</span><button type="button" onClick={save} disabled={!activeFile} className="ml-auto rounded border border-white/10 px-2 py-1 text-[10px] text-white/65 disabled:opacity-40">{status || 'Save'}</button></div><textarea value={content} onChange={(e) => { setContent(e.target.value); setStatus('Unsaved'); }} className="min-h-0 flex-1 resize-none bg-transparent leading-6 outline-none" spellCheck={false} disabled={!activeFile} /></div>; }
