function AdminPage() { const [items, setItems] = useState<{ variable: string; feature: string; description: string; configured: boolean }[]>([]); const [error, setError] = useState(''); useEffect(() => { fetch('/api/admin/configuration', { credentials: 'include' }).then(async (response) => { if (!response.ok) throw new Error((await response.json().catch(() => ({}))).error ?? 'Could not load configuration'); return response.json(); }).then(setItems).catch((reason) => setError(reason.message)); }, []); return <div className="firebox-grid min-h-[calc(100dvh-66px)] px-4 py-7 sm:px-7 sm:py-9"><div className="mx-auto max-w-[980px]"><PageTitle eyebrow="Platform configuration" title="Admin" detail="Secrets are managed only through deployment variables and are never displayed here." />{error ? <div className="rounded-xl border border-red-200 bg-red-50 p-5 text-sm text-red-700">{error}</div> : <div className="overflow-hidden rounded-xl border border-border bg-card"><div className="border-b border-border px-5 py-4 text-xs text-muted-foreground">Set these variables in your hosting provider, then redeploy. This page shows status only.</div><div className="divide-y divide-border">{items.map((item) => <div key={item.variable} className="flex items-center gap-4 px-5 py-4"><span className={`size-2 rounded-full ${item.configured ? 'bg-emerald-500' : 'bg-amber-400'}`} /><div className="min-w-0 flex-1"><div className="font-mono text-xs font-semibold">{item.variable}</div><div className="mt-1 text-xs text-muted-foreground">{item.feature} · {item.description}</div></div><span className={`rounded-full px-2 py-1 text-[10px] font-bold ${item.configured ? 'bg-emerald-500/10 text-emerald-300' : 'bg-amber-500/10 text-amber-300'}`}>{item.configured ? 'Configured' : 'Missing'}</span></div>)}</div></div>}</div></div>; }
